-- 0101-historical-characters.sql — adds 125 historical characters and their canonical 12 attributes.

CREATE TABLE IF NOT EXISTS np_attribute (
    npc_id        INTEGER PRIMARY KEY REFERENCES np_npc(id),
    name_han      TEXT,
    style_name_vi TEXT,
    birth_year    INTEGER,
    war_attr      INTEGER NOT NULL DEFAULT 50,
    ldr_attr      INTEGER NOT NULL DEFAULT 50,
    int_attr      INTEGER NOT NULL DEFAULT 50,
    pol_attr      INTEGER NOT NULL DEFAULT 50,
    dip_attr      INTEGER NOT NULL DEFAULT 50,
    com_attr      INTEGER NOT NULL DEFAULT 50,
    log_attr      INTEGER NOT NULL DEFAULT 50,
    cra_attr      INTEGER NOT NULL DEFAULT 50,
    con_attr      INTEGER NOT NULL DEFAULT 50,
    wil_attr      INTEGER NOT NULL DEFAULT 50,
    prc_attr      INTEGER NOT NULL DEFAULT 50,
    lck_attr      INTEGER NOT NULL DEFAULT 50,
    personality   TEXT,
    bio_vi        TEXT
);

