INSERT OR IGNORE INTO np_attribute (npc_id, name_han, style_name_vi, birth_year, war_attr, ldr_attr, int_attr, pol_attr, dip_attr, com_attr, log_attr, cra_attr, con_attr, wil_attr, prc_attr, lck_attr, personality, bio_vi) VALUES
    (3, '刘备', 'Huyền Đức', 160, 68, 90, 74, 78, 88, 45, 62, 52, 86, 98, 88, 90, 'BENEVOLENT', 'Hậu duệ Trung Sơn Tĩnh Vương, lòng mang nhân nghĩa cứu thế, kết nghĩa vườn đào cùng Quan Vũ, Trương Phi mưu đồ khôi phục Hán thất.'),
    (4, '张飞', 'Dực Đức', 160, 98, 84, 42, 30, 38, 55, 48, 45, 95, 82, 55, 65, 'FIERCE', 'Hào kiệt Huyện Trác, tính tình ngay thẳng cương liệt, vạn người không địch nổi, trượng nghĩa khinh tài, cùng Lưu Bị thề ước sinh tử.'),
    (5, '关羽', 'Vân Trường', 160, 98, 94, 75, 62, 65, 42, 68, 48, 92, 96, 68, 60, 'HONORABLE', 'Nghĩa sĩ Giải Lương, vũ nghệ tuyệt luân, trượng nghĩa khinh sinh, thông hiểu Xuân Thu, nghĩa khí ngút trời.'),
    (6, '张角', 'Đại Hiền Lương Sư', 160, 38, 86, 84, 70, 80, 60, 62, 55, 49, 76, 76, 76, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Thái Bình Đạo Giáo Tổ • Hoàng Cân Đại Khởi Nghĩa).'),
    (7, '张世平', 'Thương Gia', 160, 50, 60, 70, 55, 78, 88, 82, 45, 59, 62, 77, 70, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Trung Sơn Đại Mã Thương • Tiếp Tế Nghĩa Quân).'),
    (8, '卢芝荣', 'Hội Trưởng', 160, 40, 62, 68, 65, 75, 80, 74, 72, 88, 75, 72, 60, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Trác Quận Mộc Nghệ Thương Hội Trưởng).'),
    (9, '陈宝', 'Thợ Cả', 160, 45, 60, 58, 52, 55, 62, 65, 75, 98, 65, 70, 55, 'DILIGENT', 'Thợ cả xưởng dệt Lương Thị, tinh thông kỹ nghệ biên dệt giáp khiên trúc bọc da, trung thành cẩn trọng quản trị xưởng.'),
    (10, '赵安', 'Thợ Mộc', 160, 42, 50, 50, 45, 48, 55, 60, 70, 85, 92, 96, 88, 'PRAGMATIC', 'Thợ mộc kỳ cựu của Lương Gia, chuyên chế tác khung cửi dệt, xe vận tải và gia cố xưởng thủ công.'),
    (11, '卢植', 'Tử Cán', 160, 70, 89, 88, 82, 78, 50, 85, 55, 55, 92, 98, 60, 'SCHOLARLY', 'Bắc Quân Trung Lang Tướng, học trò Mã Dung, văn võ toàn tài, cương trực tiết tháo, là ân sư của Lưu Bị và Công Tôn Toản.'),
    (12, '左丰', 'Thị Lang', 160, 20, 30, 65, 60, 68, 78, 50, 20, 29, 40, 70, 64, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Thập Thường Thị Giám Quân • Triều Đình Hối Lộ Sứ).'),
    (13, '孙坚', 'Văn Đài', 160, 94, 92, 72, 65, 70, 55, 70, 50, 96, 88, 60, 72, 'VALIANT', 'Dũng tướng trứ danh thời Tam Quốc, nổi danh với võ công kiệt xuất và bản lĩnh xung trận can trường (Vũ Liệt Hoàng Đế • Giang Đông Mãnh Hổ).'),
    (14, '王允', 'Tử Sư', 160, 40, 60, 82, 84, 86, 60, 65, 45, 98, 90, 58, 55, 'BENEVOLENT', 'Trọng thần triều đình mẫu mực, thông tỏ điển chế, an định trăm họ và quản trị bang quốc đắc lực (Tư Đồ • Liên Hoàn Kế Diệt Gian Thần).'),
    (15, '刘表', 'Cảnh Thăng', 160, 52, 70, 78, 82, 80, 68, 75, 50, 58, 69, 75, 72, 'BENEVOLENT', 'Trọng thần triều đình mẫu mực, thông tỏ điển chế, an định trăm họ và quản trị bang quốc đắc lực (Kinh Châu Thứ Sử • Bát Tuấn Danh Sĩ).'),
    (16, '周瑜', 'Công Cẩn', 160, 72, 97, 96, 86, 88, 75, 88, 65, 88, 92, 90, 85, 'HONORABLE', 'Giang Đông Đại Đô Đốc, tuấn tú phong nhã, tinh thông âm luật, mưu lược tuyệt vời, người đốt cháy thuyền Tào tại Xích Bích.'),
    (17, '袁绍', 'Bản Sơ', 160, 70, 82, 70, 76, 80, 65, 75, 45, 90, 94, 78, 62, 'CAUTIOUS', 'Dòng dõi Tứ Thế Tam Công hiển hách, minh chủ 18 lộ chư hầu phạt Đổng, hùng cứ 4 châu phương Bắc.'),
    (18, '孙权', 'Trọng Mưu', 160, 68, 86, 84, 88, 88, 82, 80, 55, 80, 90, 88, 92, 'BENEVOLENT', 'Trọng thần triều đình mẫu mực, thông tỏ điển chế, an định trăm họ và quản trị bang quốc đắc lực (Đại Ngô Hoàng Đế • Sinh Tử Đương Như Tôn Trọng Mưu).'),
    (19, '张鲁', 'Công Kỳ', 160, 62, 72, 74, 78, 75, 70, 80, 50, 68, 96, 95, 72, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Hán Trung Thái Thú • Ngũ Đấu Mễ Đạo Sư).'),
    (20, '刘璋', 'Quý Ngọc', 160, 45, 55, 60, 66, 68, 70, 70, 40, 52, 55, 65, 67, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Ích Châu Mục • Thiên Phủ Chi Chủ).'),
    (21, '曹操', 'Mạnh Đức', 160, 82, 98, 94, 95, 90, 85, 92, 60, 72, 94, 92, 88, 'AMBITIOUS', 'Gian hùng thời loạn, anh hùng thời trị, túc trí đa mưu, dũng lược cái thế, chiêu hiền đãi sĩ mưu toan bá nghiệp.'),
    (22, '董卓', 'Trọng Dĩnh', 160, 86, 85, 72, 65, 50, 65, 72, 40, 73, 81, 66, 74, 'VALIANT', 'Dũng tướng trứ danh thời Tam Quốc, nổi danh với võ công kiệt xuất và bản lĩnh xung trận can trường (Thái Sư • Tây Lương Kiêu Hùng).'),
    (23, '赵云', 'Tử Long', 160, 96, 91, 76, 65, 72, 50, 78, 50, 94, 95, 85, 90, 'VALIANT', 'Dũng tướng trứ danh thời Tam Quốc, nổi danh với võ công kiệt xuất và bản lĩnh xung trận can trường (Thường Thắng Tướng Quân • Hổ Uy Đại Tướng).'),
    (24, '诸葛亮', 'Khổng Minh', 160, 38, 95, 100, 98, 95, 82, 98, 85, 62, 100, 99, 75, 'SCHOLARLY', 'Ngọa Long tiên sinh, bậc kỳ tài mưu lược thần cơ diệu toán, cúc cung tận tụy đến hơi thở cuối cùng vì nhà Hán.'),
    (25, '庞统', 'Sĩ Nguyên', 160, 34, 86, 97, 85, 84, 60, 75, 40, 60, 90, 96, 50, 'SCHOLARLY', 'Mưu sĩ kỳ tài thời loạn thế, mưu lược thâm sâu, am hiểu binh pháp và đại cục chính trị (Phượng Sồ Quân Sư • Liên Hoàn Tuyệt Mưu).'),
