    (84, '孙尚香', 'Tôn Nhân', 160, 86, 76, 68, 58, 75, 55, 60, 50, 71, 75, 66, 72, 'VALIANT', 'Dũng tướng trứ danh thời Tam Quốc, nổi danh với võ công kiệt xuất và bản lĩnh xung trận can trường (Kiêu Cơ Liệt Nữ • Cung Kiếm Nữ Binh Thống Lĩnh).'),
    (85, '大乔', 'Đại Kiều', 160, 20, 30, 74, 65, 86, 60, 50, 65, 38, 43, 72, 66, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Giang Đông Tuyệt Sắc • Tôn Sách Phu Nhân).'),
