    (89, '田丰', 'Nguyên Hạo', 160, 30, 70, 93, 86, 68, 55, 75, 40, 46, 70, 77, 74, 'SCHOLARLY', 'Mưu sĩ kỳ tài thời loạn thế, mưu lược thâm sâu, am hiểu binh pháp và đại cục chính trị (Ký Châu Đệ Nhất Mưu Sĩ • Cương Gián Trực Ngôn).'),
    (90, '审配', 'Chính Nam', 160, 65, 80, 82, 78, 55, 50, 76, 45, 64, 78, 67, 74, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Nghiệp Thành Tử Thủ • Trung Liệt Ký Châu Thần).'),
    (91, '李儒', 'Văn Ưu', 160, 32, 65, 93, 74, 78, 65, 70, 40, 45, 68, 82, 74, 'SCHOLARLY', 'Mưu sĩ kỳ tài thời loạn thế, mưu lược thâm sâu, am hiểu binh pháp và đại cục chính trị (Tây Lương Độc Mưu • Đổng Trác Tâm Phúc Quân Sư).'),
    (92, '华雄', 'Hoa Hùng', 160, 92, 82, 50, 35, 40, 40, 60, 40, 72, 73, 45, 70, 'VALIANT', 'Dũng tướng trứ danh thời Tam Quốc, nổi danh với võ công kiệt xuất và bản lĩnh xung trận can trường (Tây Lương Kiêu Tướng • Trảm Tướng Tị Thủy Quan).'),
    (93, '张任', 'Trương Nhiệm', 160, 84, 86, 76, 60, 50, 45, 70, 45, 72, 82, 62, 74, 'PRAGMATIC', 'Nhân vật lịch sử thời Tam Quốc, có nhiều đóng góp và ảnh hưởng trên chính trường (Xuyên Trung Danh Tướng • Lạc Phượng Pha Mai Phục Trảm Bàng Thống).'),
    (94, '蔡文姬', 'Văn Cơ', 160, 20, 35, 86, 70, 88, 50, 50, 75, 40, 50, 76, 68, 'SCHOLARLY', 'Mưu sĩ kỳ tài thời loạn thế, mưu lược thâm sâu, am hiểu binh pháp và đại cục chính trị (Hồ Gia Thập Bát Phách • Tuyệt Đại Tài Nữ).'),
    (95, '左慈', 'Ô Giác Tiên Sinh', 160, 55, 60, 96, 50, 85, 50, 65, 92, 65, 72, 80, 73, 'SCHOLARLY', 'Mưu sĩ kỳ tài thời loạn thế, mưu lược thâm sâu, am hiểu binh pháp và đại cục chính trị (Nga Mi Ảo Thuật Chân Tiên • Độn Giáp Thiên Thư).'),
    (96, '周瑜', 'Công Cẩn', 160, 72, 97, 96, 88, 92, 60, 85, 70, 76, 92, 84, 79, 'Điềm đạm', 'Đại đô đốc trẻ tuổi tài hoa xuất chúng của Đông Ngô, chỉ huy hỏa thiêu Xích Bích tan tành trăm vạn quân Tào.'),
    (97, '陸遜', 'Bá Ngôn', 160, 69, 96, 95, 90, 85, 65, 88, 60, 73, 90, 84, 79, 'Điềm đạm', 'Thiếu niên tướng quân nho nhã, hỏa thiêu 700 dặm liên doanh của Lưu Bị tại Di Lăng.'),
    (98, '呂蒙', 'Tử Minh', 160, 82, 91, 89, 78, 76, 60, 80, 55, 76, 88, 78, 77, 'Điềm đạm', 'Tướng võ kiêm văn, áo trắng qua sông tập kích Kinh Châu, lập đại công cho Tôn Quyền.'),
    (99, '太史慈', 'Tử Nghĩa', 160, 93, 84, 70, 58, 68, 45, 65, 60, 78, 81, 62, 73, 'Điềm đạm', 'Dũng tướng thiện xạ bậc nhất Đông Lai, trung can nghĩa khí, một đời lập nhiều chiến công hiển hách.'),
    (100, '龐統', 'Sĩ Nguyên', 160, 34, 85, 97, 86, 88, 50, 78, 50, 50, 79, 81, 77, 'Điềm đạm', 'Phượng Sồ trứ danh sánh ngang Ngọa Long, bày liên hoàn kế hỏa thiêu Xích Bích.'),
    (101, '法正', 'Hiếu Trực', 160, 48, 82, 94, 80, 78, 60, 82, 52, 59, 79, 81, 76, 'Điềm đạm', 'Mưu sĩ đắc lực nhất của Lưu Bị khi đoạt Ba Thục và đại thắng Hán Trung chém Hạ Hầu Uyên.'),
    (102, '馬超', 'Mạnh Khởi', 160, 97, 88, 52, 38, 60, 45, 65, 50, 78, 77, 52, 71, 'Điềm đạm', 'Cẩm Mã Siêu dũng mãnh vô song, thống lĩnh thiết kỵ Tây Lương làm Tào Tháo phải cắt râu cởi áo trốn chạy.'),
    (103, '黃忠', 'Hán Thăng', 160, 93, 86, 66, 55, 60, 40, 70, 58, 79, 80, 57, 73, 'Điềm đạm', 'Lão tướng bách bộ xuyên dương giương cung bắn đâu trúng đó, chém tướng đoạt ải Định Quân Sơn.'),
    (104, '魏延', 'Văn Trường', 160, 91, 85, 70, 50, 52, 45, 72, 60, 79, 81, 59, 73, 'Điềm đạm', 'Dũng tướng trấn thủ Hán Trung vững như bàn thạch, người hiến Tí Ngọ Cốc kỳ mưu.'),
    (105, '貂蟬', 'Bế Nguyệt', 160, 28, 45, 84, 72, 98, 65, 50, 70, 43, 55, 81, 69, 'Điềm đạm', 'Sắc đẹp bế nguyệt khiến trăng phải thẹn giấu mình, một tay xoay vần thế cục tiêu diệt Đổng Trác.'),
    (106, '麋竺', 'Tử Trọng', 160, 35, 65, 78, 82, 80, 94, 90, 60, 56, 64, 83, 71, 'Điềm đạm', 'Cự thương Từ Châu giàu nứt đố đổ vách, hiến trọn gia tài muôn lượng bạc ủng hộ Lưu Bị khởi nghiệp.'),
    (107, '甄宓', 'Văn Chiêu', 160, 25, 50, 85, 76, 95, 75, 65, 82, 48, 57, 84, 70, 'Điềm đạm', 'Tuyệt sắc giai nhân phương Bắc, phong tư yểu điệu, thấu suốt kinh sử và cầm kỳ thi họa.'),
    (108, '王老七', 'Bản Đạo', 160, 35, 60, 72, 68, 75, 82, 78, 45, 50, 59, 76, 70, 'Điềm đạm', 'Chưởng quỹ dày dạn kinh nghiệm tại chợ Trác Huyện, tính toán sổ sách nhanh như chớp.'),
    (109, '李鐵鎚', 'Đại Lực', 160, 62, 45, 45, 35, 40, 50, 60, 85, 66, 48, 46, 64, 'Điềm đạm', 'Thợ cả lò rèn cơ bắp cuồn cuộn, kéo bễ nung thép bách luyện đạt độ tinh xảo cao.'),
    (110, '趙勇', 'Bá Đao', 160, 76, 70, 50, 40, 55, 45, 68, 50, 68, 64, 50, 68, 'Điềm đạm', 'Tiêu đầu áp tải xe ngựa nổi danh trung kiên, đường đao dũng mãnh đập tan nhiều toán thổ phỉ.'),
    (111, '張田父', 'Nông Lão', 160, 45, 65, 55, 60, 50, 58, 72, 74, 59, 58, 55, 68, 'Điềm đạm', 'Nông phu cả đời gắn bó với đồng ruộng, thông thạo mùa vụ và dẫn thủy nhập điền.'),
    (112, '孫耀', 'Kim Bảo', 160, 30, 65, 80, 78, 84, 89, 85, 40, 48, 63, 84, 72, 'Điềm đạm', 'Chưởng quỹ tiền trang lớn ở Lạc Dương, quen biết quan lại và am hiểu giá cả các châu.'),
    (113, '歐陽鑄', 'Xích Hỏa', 160, 55, 50, 68, 45, 42, 55, 65, 91, 65, 57, 59, 68, 'Điềm đạm', 'Hậu duệ kiếm sư Âu Dã Tử, bí thuật tôi thép bằng thảo dược độc môn.'),
    (114, '許護威', 'Thiết Bích', 160, 83, 76, 58, 50, 62, 50, 74, 52, 74, 71, 56, 70, 'Điềm đạm', 'Võ sĩ hộ tống danh tiếng kinh thành, một tay đại đao áp tải vạn lượng bạc bình an.'),
    (115, '甄福德', 'Đại Lương', 160, 35, 68, 75, 74, 78, 86, 88, 50, 54, 64, 79, 71, 'Điềm đạm', 'Chuyên gia điều phối kho lương thảo Ký Châu, quản lý thu mua vận chuyển chuyên nghiệp.'),
    (116, '柳娘', 'Tơ Lụa', 160, 20, 60, 65, 55, 65, 70, 68, 88, 48, 54, 66, 69, 'Điềm đạm', 'Nghệ nhân dệt vải nổi danh vùng Nghiệp Thành, hoa văn thêu tinh xảo quý tộc ưa chuộng.'),
    (117, '馬路', 'Hoa Tiêu', 160, 50, 55, 60, 40, 50, 60, 86, 65, 64, 56, 58, 67, 'Điềm đạm', 'Xa phu dày dạn nắng gió phương Bắc, thuộc làu từng khúc quanh và dịch trạm tránh bão tuyết.'),
    (118, '鄭婉兒', 'Thục Gấm', 160, 22, 55, 70, 60, 72, 74, 65, 93, 49, 54, 72, 69, 'Điềm đạm', 'Đệ nhất nghệ nhân dệt gấm Thành Đô, lụa dệt ra giá trị nghìn vàng.'),
    (119, '張百草', 'Dược Vương', 160, 25, 50, 86, 65, 70, 68, 75, 87, 52, 58, 77, 70, 'Điềm đạm', 'Bậc thầy phối chế đan dược và cao dán trị ngoại thương thương binh.'),
    (120, '姜險', 'Hẻm Núi', 160, 79, 72, 62, 45, 52, 45, 78, 55, 74, 70, 55, 70, 'Điềm đạm', 'Chuyên gia bảo vệ thương đoàn vượt qua đường ván gỗ hiểm trở Hán Trung - Ba Thục.'),
    (121, '馬良駒', 'Bá Mã', 160, 68, 65, 65, 50, 70, 84, 80, 62, 70, 66, 72, 70, 'Điềm đạm', 'Thương gia sành sỏi về ngựa giống Tây Lương, tuyển chọn tuấn mã hàng đầu.'),
    (122, '哈神', 'Tây Vực', 160, 58, 58, 62, 40, 65, 62, 88, 50, 65, 59, 63, 68, 'Điềm đạm', 'Thông thạo con đường tơ lụa và sa mạc cát bụi, định hướng bằng sao trời.'),
    (123, '海鹽子', 'Duyên Hải', 160, 40, 62, 72, 68, 76, 87, 82, 60, 57, 61, 77, 70, 'Điềm đạm', 'Trùm buôn muối duyên hải Hạ Phì, nắm giữ mạng lưới phân phối muối biển liên tỉnh.'),
    (124, '陸水', 'Sóng Biển', 160, 65, 74, 68, 45, 60, 58, 89, 70, 73, 70, 63, 71, 'Điềm đạm', 'Thủy thủ lão luyện Trường Giang, thuộc từng ghềnh đá và ngọn sóng ngầm Xích Bích.'),
    (125, '顧定', 'Trung Hậu', 160, 30, 75, 78, 82, 78, 75, 80, 60, 51, 67, 77, 73, 'Điềm đạm', 'Quản gia trung thành tột bậc, quán xuyến mọi việc nhà cửa, gia đinh và thu chi nội bộ.'),
    (126, '鐵頭', 'Khoáng Sơn', 160, 55, 65, 50, 40, 45, 52, 74, 84, 66, 58, 50, 67, 'Điềm đạm', 'Phu mỏ sắt Thượng Đảng, nhạy bén ngửi mùi đất đá tìm ra vỉa quặng thượng hạng.'),
    (127, '林香', 'Nam Hải', 160, 32, 58, 74, 68, 82, 88, 80, 65, 53, 58, 80, 70, 'Điềm đạm', 'Thương nhân Giao Châu am hiểu thị trường hương liệu và ngọc trai phương Nam.');
